-- LABORATORIO CLINICO: INSTALACION DE PRUEBAS PARA HEIDISQL
-- Requiere MySQL 8.0 o posterior. Codificacion UTF-8.
-- HeidiSQL: Archivo > Cargar archivo SQL; ejecutar TODO el archivo (F9).
-- Usar una conexion con permisos para crear bases y tablas.
-- Crea una base NUEVA laboratorio_pruebas. Si ya existe, detenerse en el primer error.
-- No usar la opcion de continuar/ignorar errores. No contiene DROP, DELETE ni reemplazos.
-- Para otro nombre, cambiar CREATE DATABASE y USE antes de ejecutar.
-- Datos ficticios: 30 estudios, 57 analitos, 10 pacientes, 5 medicos,
-- 3 companias, 6 tipos de muestra, 7 metodos y 120 precios ilustrativos.
-- Incluye 2 solicitudes y 1 cotizacion; sin pagos ni resultados clinicos.
-- Usuarios: admin, recepcion, caja, laboratorista, responsable.
-- Clave temporal de TODOS: Admin1.1 (bcrypt; cambio obligatorio al entrar).
-- No es una exportacion de la base operativa del equipo de origen.
-- Despues, configurar app/Config/database.local.php con database=laboratorio_pruebas
-- y las credenciales MySQL del equipo destino; este SQL no modifica archivos PHP.

CREATE DATABASE `laboratorio_pruebas` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `laboratorio_pruebas`;
SET NAMES utf8mb4;
SET @lab_sql_mode_previo = @@SESSION.sql_mode;
SET @lab_zona_previa = @@SESSION.time_zone;
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,NO_AUTO_VALUE_ON_ZERO,NO_BACKSLASH_ESCAPES';
SET SESSION time_zone = '-06:00';

-- Estructura completa, incluidas migraciones de resultados, cobros y devoluciones.
-- Las tablas se ordenan por sus dependencias; las claves foraneas permanecen activas.

CREATE TABLE `bitacora_actividad` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `usuario_id` bigint(20) unsigned DEFAULT NULL,
  `usuario_nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tipo` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `referencia` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resumen` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `detalle` json NOT NULL,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_bitacora_fecha` (`creado_en`,`id`),
  KEY `ix_bitacora_actor` (`usuario_id`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=249 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `companias` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `codigo` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `razon_social` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `rfc` varchar(13) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `contacto` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `telefono` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `correo` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `direccion` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `notas` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `version` int(10) unsigned NOT NULL DEFAULT '1',
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo` (`codigo`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `empresa` (
  `id` tinyint(3) unsigned NOT NULL DEFAULT '1',
  `nombre_comercial` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `razon_social` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rfc` varchar(13) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `telefono` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `correo` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sitio_web` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `direccion` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `codigo_postal` char(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `logo_ruta` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ruta relativa en storage, nunca una URL externa',
  `color_primario` char(7) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#176549',
  `color_secundario` char(7) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#FFFFFF',
  `color_acento` char(7) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#AA5A17',
  `encabezado_ticket` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pie_ticket` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `moneda` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MXN',
  `zona_horaria` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'America/Mexico_City',
  `version` int(10) unsigned NOT NULL DEFAULT '1',
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  CONSTRAINT `ck_color_acento` CHECK (regexp_like(`color_acento`,_utf8mb4'^#[0-9A-Fa-f]{6}$')),
  CONSTRAINT `ck_color_primario` CHECK (regexp_like(`color_primario`,_utf8mb4'^#[0-9A-Fa-f]{6}$')),
  CONSTRAINT `ck_color_secundario` CHECK (regexp_like(`color_secundario`,_utf8mb4'^#[0-9A-Fa-f]{6}$')),
  CONSTRAINT `ck_empresa_unica` CHECK ((`id` = 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Datos y colores del negocio, una sola configuración';

CREATE TABLE `instalacion_demo` (
  `id` tinyint(3) unsigned NOT NULL,
  `firma` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `completa` tinyint(4) NOT NULL DEFAULT '0',
  `creado_en` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `intentos_acceso` (
  `clave` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `inicio` bigint(20) NOT NULL,
  `intentos` int(10) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`clave`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `medicos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `codigo` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `apellidos` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `cedula` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `especialidad` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `telefono` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `correo` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `direccion` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `notas` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `version` int(10) unsigned NOT NULL DEFAULT '1',
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo` (`codigo`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `metodos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `codigo` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `version` int(10) unsigned NOT NULL DEFAULT '1',
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo` (`codigo`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `roles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `nombre` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `permisos` json NOT NULL,
  `protegido` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `nombre` (`nombre`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `schema_migrations` (
  `clave` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `aplicado_en` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`clave`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `tipos_muestra` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `codigo` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `recipiente` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `indicaciones` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `version` int(10) unsigned NOT NULL DEFAULT '1',
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo` (`codigo`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `analitos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `codigo` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `unidad` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `tipo_resultado` enum('numerico','cualitativo','texto') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'numerico',
  `decimales` tinyint(3) unsigned NOT NULL DEFAULT '2',
  `metodo_id` bigint(20) unsigned DEFAULT NULL,
  `notas` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `version` int(10) unsigned NOT NULL DEFAULT '1',
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `referencia_texto` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo` (`codigo`),
  KEY `metodo_id` (`metodo_id`),
  CONSTRAINT `analitos_ibfk_1` FOREIGN KEY (`metodo_id`) REFERENCES `metodos` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `estudios` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `codigo` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `area` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `tipo_muestra_id` bigint(20) unsigned DEFAULT NULL,
  `metodo_id` bigint(20) unsigned DEFAULT NULL,
  `tiempo_entrega` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `indicaciones` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `version` int(10) unsigned NOT NULL DEFAULT '1',
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo` (`codigo`),
  KEY `tipo_muestra_id` (`tipo_muestra_id`),
  KEY `metodo_id` (`metodo_id`),
  CONSTRAINT `estudios_ibfk_1` FOREIGN KEY (`tipo_muestra_id`) REFERENCES `tipos_muestra` (`id`),
  CONSTRAINT `estudios_ibfk_2` FOREIGN KEY (`metodo_id`) REFERENCES `metodos` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `pacientes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `codigo` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `apellidos` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fecha_nacimiento` date NOT NULL,
  `sexo` enum('femenino','masculino','otro','no_especificado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'no_especificado',
  `telefono` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `correo` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `direccion` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `medico_id` bigint(20) unsigned DEFAULT NULL,
  `compania_id` bigint(20) unsigned DEFAULT NULL,
  `notas` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `version` int(10) unsigned NOT NULL DEFAULT '1',
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo` (`codigo`),
  KEY `medico_id` (`medico_id`),
  KEY `compania_id` (`compania_id`),
  KEY `ix_paciente_nombre` (`apellidos`,`nombre`),
  CONSTRAINT `pacientes_ibfk_1` FOREIGN KEY (`medico_id`) REFERENCES `medicos` (`id`),
  CONSTRAINT `pacientes_ibfk_2` FOREIGN KEY (`compania_id`) REFERENCES `companias` (`id`),
  CONSTRAINT `ck_paciente_fecha_nacimiento` CHECK ((`fecha_nacimiento` >= _utf8mb4'1800-01-01'))
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `usuarios` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `rol_id` bigint(20) unsigned NOT NULL,
  `nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre_usuario` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `contrasena_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `cambio_obligatorio` tinyint(1) NOT NULL DEFAULT '1',
  `ultimo_acceso` timestamp NULL DEFAULT NULL,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `nombre_usuario` (`nombre_usuario`),
  KEY `rol_id` (`rol_id`),
  CONSTRAINT `usuarios_ibfk_1` FOREIGN KEY (`rol_id`) REFERENCES `roles` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `caja_turnos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `usuario_id` bigint(20) unsigned NOT NULL,
  `estado` enum('abierto','cerrado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'abierto',
  `usuario_abierto` bigint(20) unsigned GENERATED ALWAYS AS ((case when (`estado` = _utf8mb4'abierto') then `usuario_id` else NULL end)) STORED,
  `fondo` decimal(12,2) NOT NULL,
  `version` int(10) unsigned NOT NULL DEFAULT '1',
  `resumen_cierre` json DEFAULT NULL,
  `abierto_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `cerrado_en` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_usuario_turno` (`usuario_abierto`),
  KEY `usuario_id` (`usuario_id`),
  CONSTRAINT `caja_turnos_ibfk_1` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `estudio_analitos` (
  `estudio_id` bigint(20) unsigned NOT NULL,
  `analito_id` bigint(20) unsigned NOT NULL,
  `orden` int(10) unsigned NOT NULL,
  PRIMARY KEY (`estudio_id`,`analito_id`),
  UNIQUE KEY `uq_estudio_orden` (`estudio_id`,`orden`),
  KEY `analito_id` (`analito_id`),
  CONSTRAINT `estudio_analitos_ibfk_1` FOREIGN KEY (`estudio_id`) REFERENCES `estudios` (`id`),
  CONSTRAINT `estudio_analitos_ibfk_2` FOREIGN KEY (`analito_id`) REFERENCES `analitos` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `precios` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `estudio_id` bigint(20) unsigned NOT NULL,
  `compania_id` bigint(20) unsigned DEFAULT NULL,
  `compania_ambito` bigint(20) unsigned GENERATED ALWAYS AS (ifnull(`compania_id`,0)) STORED,
  `importe` decimal(12,2) NOT NULL,
  `moneda` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MXN',
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `version` int(10) unsigned NOT NULL DEFAULT '1',
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_precio_estudio_compania` (`estudio_id`,`compania_ambito`),
  KEY `compania_id` (`compania_id`),
  CONSTRAINT `precios_ibfk_1` FOREIGN KEY (`estudio_id`) REFERENCES `estudios` (`id`),
  CONSTRAINT `precios_ibfk_2` FOREIGN KEY (`compania_id`) REFERENCES `companias` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `solicitudes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `paciente_id` bigint(20) unsigned DEFAULT NULL,
  `medico_id` bigint(20) unsigned DEFAULT NULL,
  `compania_id` bigint(20) unsigned DEFAULT NULL,
  `estado` enum('cotizacion','registrada','cancelada') COLLATE utf8mb4_unicode_ci NOT NULL,
  `datos` json NOT NULL,
  `total` decimal(12,2) NOT NULL,
  `version` int(10) unsigned NOT NULL DEFAULT '1',
  `creado_por` bigint(20) unsigned NOT NULL,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `medico_id` (`medico_id`),
  KEY `compania_id` (`compania_id`),
  KEY `ix_solicitud_paciente` (`paciente_id`,`id`),
  CONSTRAINT `solicitudes_ibfk_1` FOREIGN KEY (`paciente_id`) REFERENCES `pacientes` (`id`),
  CONSTRAINT `solicitudes_ibfk_2` FOREIGN KEY (`medico_id`) REFERENCES `medicos` (`id`),
  CONSTRAINT `solicitudes_ibfk_3` FOREIGN KEY (`compania_id`) REFERENCES `companias` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `caja_movimientos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `turno_id` bigint(20) unsigned NOT NULL,
  `usuario_id` bigint(20) unsigned NOT NULL,
  `tipo` enum('ingreso','egreso') COLLATE utf8mb4_unicode_ci NOT NULL,
  `metodo` enum('efectivo','tarjeta','transferencia') COLLATE utf8mb4_unicode_ci NOT NULL,
  `importe` decimal(12,2) NOT NULL,
  `concepto` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `referencia` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `clave` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_movimiento_clave` (`clave`),
  KEY `turno_id` (`turno_id`),
  CONSTRAINT `caja_movimientos_ibfk_1` FOREIGN KEY (`turno_id`) REFERENCES `caja_turnos` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `resultados` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `referencia` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` int(10) unsigned NOT NULL DEFAULT '1',
  `estado` enum('borrador','validado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'borrador',
  `creado_por` bigint(20) unsigned NOT NULL,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `solicitud_id` bigint(20) unsigned DEFAULT NULL,
  `estudio_id` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `referencia` (`referencia`),
  UNIQUE KEY `uq_resultado_solicitud_estudio` (`solicitud_id`,`estudio_id`),
  KEY `estudio_id` (`estudio_id`),
  CONSTRAINT `resultados_ibfk_1` FOREIGN KEY (`solicitud_id`) REFERENCES `solicitudes` (`id`),
  CONSTRAINT `resultados_ibfk_2` FOREIGN KEY (`estudio_id`) REFERENCES `estudios` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `resultado_versiones` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `resultado_id` bigint(20) unsigned NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `contenido` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `motivo` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `usuario_id` bigint(20) unsigned NOT NULL,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `datos_analitos` json DEFAULT NULL,
  `contexto` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_resultado_version` (`resultado_id`,`version`),
  CONSTRAINT `resultado_versiones_ibfk_1` FOREIGN KEY (`resultado_id`) REFERENCES `resultados` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `solicitud_pagos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `solicitud_id` bigint(20) unsigned NOT NULL,
  `turno_id` bigint(20) unsigned NOT NULL,
  `movimiento_id` bigint(20) unsigned NOT NULL,
  `usuario_id` bigint(20) unsigned NOT NULL,
  `tipo` enum('anticipo','abono','liquidacion') COLLATE utf8mb4_unicode_ci NOT NULL,
  `importe` decimal(12,2) NOT NULL,
  `metodo` enum('efectivo','tarjeta','transferencia') COLLATE utf8mb4_unicode_ci NOT NULL,
  `recibido` decimal(12,2) DEFAULT NULL,
  `cambio` decimal(12,2) NOT NULL DEFAULT '0.00',
  `referencia` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `notas` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `clave` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `huella` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `datos` json NOT NULL,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pago_clave` (`clave`),
  UNIQUE KEY `uq_pago_movimiento` (`movimiento_id`),
  KEY `ix_pagos_solicitud` (`solicitud_id`,`id`),
  KEY `ix_pagos_turno` (`turno_id`,`id`),
  KEY `usuario_id` (`usuario_id`),
  CONSTRAINT `solicitud_pagos_ibfk_1` FOREIGN KEY (`solicitud_id`) REFERENCES `solicitudes` (`id`),
  CONSTRAINT `solicitud_pagos_ibfk_2` FOREIGN KEY (`turno_id`) REFERENCES `caja_turnos` (`id`),
  CONSTRAINT `solicitud_pagos_ibfk_3` FOREIGN KEY (`movimiento_id`) REFERENCES `caja_movimientos` (`id`),
  CONSTRAINT `solicitud_pagos_ibfk_4` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `resultado_validaciones` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `resultado_id` bigint(20) unsigned NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `usuario_id` bigint(20) unsigned NOT NULL,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_nombre` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_validacion` (`resultado_id`,`version`),
  CONSTRAINT `resultado_validaciones_ibfk_1` FOREIGN KEY (`resultado_id`, `version`) REFERENCES `resultado_versiones` (`resultado_id`, `version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `solicitud_acciones` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `solicitud_id` bigint(20) unsigned NOT NULL,
  `pago_id` bigint(20) unsigned DEFAULT NULL,
  `tipo` enum('cancelacion','devolucion') COLLATE utf8mb4_unicode_ci NOT NULL,
  `estado` enum('pendiente','aprobada','realizada','rechazada') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pendiente',
  `importe` decimal(12,2) DEFAULT NULL,
  `metodo` enum('efectivo','tarjeta','transferencia') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `motivo` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `solicitante_id` bigint(20) unsigned NOT NULL,
  `solicitante_nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `autorizador_id` bigint(20) unsigned DEFAULT NULL,
  `autorizador_nombre` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `motivo_decision` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ejecutor_id` bigint(20) unsigned DEFAULT NULL,
  `turno_id` bigint(20) unsigned DEFAULT NULL,
  `movimiento_id` bigint(20) unsigned DEFAULT NULL,
  `clave` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `huella` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `datos` json DEFAULT NULL,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `decidido_en` timestamp NULL DEFAULT NULL,
  `realizado_en` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_accion_clave` (`clave`),
  UNIQUE KEY `uq_accion_movimiento` (`movimiento_id`),
  KEY `ix_accion_solicitud` (`solicitud_id`,`id`),
  KEY `ix_accion_pago` (`pago_id`,`estado`),
  KEY `ix_accion_estado` (`estado`,`id`),
  KEY `solicitante_id` (`solicitante_id`),
  KEY `autorizador_id` (`autorizador_id`),
  KEY `ejecutor_id` (`ejecutor_id`),
  KEY `turno_id` (`turno_id`),
  CONSTRAINT `solicitud_acciones_ibfk_1` FOREIGN KEY (`solicitud_id`) REFERENCES `solicitudes` (`id`),
  CONSTRAINT `solicitud_acciones_ibfk_2` FOREIGN KEY (`pago_id`) REFERENCES `solicitud_pagos` (`id`),
  CONSTRAINT `solicitud_acciones_ibfk_3` FOREIGN KEY (`solicitante_id`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `solicitud_acciones_ibfk_4` FOREIGN KEY (`autorizador_id`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `solicitud_acciones_ibfk_5` FOREIGN KEY (`ejecutor_id`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `solicitud_acciones_ibfk_6` FOREIGN KEY (`turno_id`) REFERENCES `caja_turnos` (`id`),
  CONSTRAINT `solicitud_acciones_ibfk_7` FOREIGN KEY (`movimiento_id`) REFERENCES `caja_movimientos` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `resultado_entregas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `resultado_id` bigint(20) unsigned NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `usuario_id` bigint(20) unsigned NOT NULL,
  `destinatario` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `resultado_id` (`resultado_id`,`version`),
  CONSTRAINT `resultado_entregas_ibfk_1` FOREIGN KEY (`resultado_id`, `version`) REFERENCES `resultado_validaciones` (`resultado_id`, `version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

